sys_script_include.script:
function AppBuilderImplementBusinessProcess(vApp,business_process)
{

/*

	TEST SCRIPT

	var strScope = 'x_snc_test_process';
	var grApp = x_snc_devtools.GetAppRecord(strScope);
	var grMetaData = new GlideRecord('sys_metadata');
	grMetaData.addQuery('sys_scope','=',grApp.sys_id);
	grMetaData.query();
	while(grMetaData.next())
	{
		gs.info(x_snc_devtools.RenderRecordSummary(grMetaData));
		if (grMetaData.sys_class_name == 'sys_db_object')
		{
			var grDbObject = GetTableRecord(grMetaData.sys_id);
			x_snc_devtools.TableDelete(grDbObject.name);
		}
		else
		{
			x_snc_devtools.GlideRecordDelete(grMetaData,true);
		}
	}

	var business_process = x_snc_devtools.BusinessProcessGetExample();
	gs.info(x_snc_devtools.RenderValue(business_process));

	x_snc_devtools.AppBuilderImplementBusinessProcess(strScope,business_process);


*/


	var grApp = GetAppRecord(vApp);

	if (IsValidRecord(grApp) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: App could not be loaded.');
		return false;
	}

	if (grApp.scope == 'global')
	{
		LogError('AppBuilderImplementBusinessProcess: Global Apps are not supported.');
		return false;
	}

	var result = BusinessProcessValidate(business_process,true);

	if (result.valid == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Business Process is invalid:\n' + RenderValue(result));
		return false;
	}

	var strParentTable = GetStringValue(GetValue(business_process,'parent_table'));
	if (strParentTable == '')
	{
		strParentTable = 'task';
	}
	var grParentTable = GetTableRecord(strParentTable);
	if (IsValidRecord(grParentTable) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Could not load parent table: ' + strParentTable);
		return false;
	}
	if (strParentTable != 'task' && IsDerivedFromTable(grParentTable,'task') == false)
	{
		LogError('AppBuilderImplementBusinessProcess: The parent table ("' + strParentTable + '") must be "task" or derived from "task"!');
		return false;
	}

	// Prepare for implementation
	business_process = BusinessProcessPrepareImplementation(business_process, grApp);
	if (business_process == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Failed to prepare the business process for implementation!');
		return false;
	}


	var strScope = GetStringValue(grApp.scope);
	var strScopeSysId = GetStringValue(grApp.sys_id);
	var strProcessId = GetStringValue(GetValue(business_process,'id'));
	var strProcessName = GetStringValue(GetValue(business_process,'name'));
	var strProcessClassName = GetStringValue(GetValue(business_process,'class_name'));



	// SCRIPT INCLUDE with business process class

	var strScript = '';
	strScript += "var " + strProcessClassName + " = Class.create();\n";
	strScript += strProcessClassName + ".prototype = Object.extendsObject(x_snc_devtools.BusinessProcessAPI,\n";
	strScript += "{\n";

	// business process object
	var strJson = MakeJson(business_process);
	strJson = '\t' + StringReplace(strJson,'\n','\n\t'); 

	strScript += "\tbusiness_process:\n";
	strScript += strJson + ",\n";
	strScript += "\t\n";

	// initialize
	strScript += "\tinitialize: function()\n";
	strScript += "\t{\n";
	strScript += "\t},\n";
	strScript += "\t\n";

	// onBeforeInsert
	strScript += "\tonBeforeInsert: function(grProcess)\n";
	strScript += "\t{\n";
	strScript += "\t\tgs.addInfoMessage(grProcess.number + ' is being inserted.');\n";
	strScript += "\t\treturn true; // return true if the insert can proceed, false if not\n";
	strScript += "\t},\n";
	strScript += "\t\n";

	// onBeforeUpdate
	strScript += "\tonBeforeUpdate: function(grProcess, grProcessPrevious)\n";
	strScript += "\t{\n";
	strScript += "\t\tgs.addInfoMessage(grProcess.number + ' is being updated.');\n";
	strScript += "\t\treturn true; // return true if the update can proceed, false if not\n";
	strScript += "\t},\n";
	strScript += "\t\n";	

	// onStateChange
	strScript += "\tonStateChange: function(grProcess, strCurrentStateId, strTargetStateId)\n";
	strScript += "\t{\n";
	strScript += "\t\tgs.addInfoMessage(grProcess.number + ' changes state from \"' + strOldStateId + '\" to \"' + strTargetStateId + '\"');\n";
	strScript += "\t\treturn true; // return true if the state change can proceed, false if not\n";
	strScript += "\t},\n";
	strScript += "\t\n";

	// type
	strScript += "\ttype: '"+strProcessClassName+"'\n";
	strScript += "})";


	var strDescription = 'The ' + strProcessClassName + ' implements the "' + strProcessName+ '" process.';

	var strScriptIncludeSysId = RecordInsertOrUpdate(
			'sys_script_include',
			{
				sys_scope: strScopeSysId,
				name: strProcessClassName
			},
			{
				access: 'public',
				description: strDescription,
				script: strScript
			},
			{
			});


	// ROLES

	var aRoles = GetValue(business_process,'_roles');

	var roleViewer = ArrayGetElementById(aRoles, 'viewer');
	if (IsObject(roleViewer) == false)
	{
		roleViewer = {
			id: 'viewer',
			description: 'A user that can view all data related to the process.'
			};
		aRoles.push(roleViewer);
	}

	var roleManager = ArrayGetElementById(aRoles, 'manager');
	if (IsObject(roleManager) == false)
	{
		roleManager = {
			id: 'manager',
			description: 'A user that can view and edit all data related to the process.'
			};
		aRoles.push(roleManager);
	}	

	var roleAdmin = ArrayGetElementById(aRoles, 'admin');
	if (IsObject(roleAdmin) == false)
	{
		roleAdmin = {
			id: 'admin',
			description: 'A user that can view, edit and delete all data related to the process.'
			};
		aRoles.push(roleAdmin);
	}

	for (var nRole = 0; nRole < aRoles.length; nRole++)
	{
		var role = aRoles[nRole];

		var strRoleSuffix = GetStringValue(GetValue(role,'id'));
		var strRoleName = strScope + '.' + strRoleSuffix;
		var strRoleDescription = GetStringValue(GetValue(role,'description'));

		var strRoleSysId = RecordInsertOrUpdate(
			'sys_user_role',
			{
				sys_scope: strScopeSysId,
				suffix: strRoleSuffix,
				name: strRoleName
			},
			{
			},
			{
				description: strRoleDescription
			});
		if (IsValidSysId(strRoleSysId) == false)
		{
			LogError('AppBuilderImplementBusinessProcess: Could not create/update role: ' + strRoleName);
			return false;
		}
		aRoles[nRole]['sys_id'] = strRoleSysId;
		aRoles[nRole]['name'] = strRoleName;
	}

	var roleAdmin = ArrayGetElementById(aRoles, 'admin');
	var roleManager = ArrayGetElementById(aRoles, 'manager');
	var roleViewer = ArrayGetElementById(aRoles, 'viewer');


	var strRoleContainsSysId = RecordInsertOrUpdate(
		'sys_user_role_contains',
		{
			sys_scope: strScopeSysId,
			role: roleAdmin.sys_id,
			contains: roleManager.sys_id
		},{},{});
	if (IsValidSysId(strRoleContainsSysId) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Could not add role manager to role admin.');
		return false;
	}

	for (var nRole = 0; nRole < aRoles.length; nRole++)
	{
		var role = aRoles[nRole];
		var strId = role['id'];
		if (strId != 'admin' && strId != 'viewer')
		{
			var strRoleContainsSysId = RecordInsertOrUpdate(
				'sys_user_role_contains',
				{
					sys_scope: strScopeSysId,
					role: role.sys_id,
					contains: roleViewer.sys_id
				},{},{});
			if (IsValidSysId(strRoleContainsSysId) == false)
			{
				LogError('AppBuilderImplementBusinessProcess: Could not add role viewer to role '+strId+'.');
				return false;
			}
		}
	}

	// TABLE

	var strTableLabel = strProcessName;

	var strTableSysId = TableCreate(strScopeSysId,strProcessId,strTableLabel,strParentTable);

	if (IsValidSysId(strTableSysId) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Could not create/update table: *' + strProcessId);
		return false;
	}

	var grTable = GetTableRecord(strTableSysId);
	if (IsValidRecord(grTable) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Could not load table record: ' + strTableSysId);
		return false;
	}
	var strTableName = GetStringValue(grTable.name);


	// ACLs

	AppBuilderAclInsertOrUpdate(
		grApp,
		'record',
		'create',
		strTableName,
		'allow',
		'Allows users with process manager role create access to the table',
		[roleManager.name],
		null);		


	AppBuilderAclInsertOrUpdate(
		grApp,
		'record',
		'read',
		strTableName,
		'allow',
		'Allows users with process viewer role read access to the table',
		[roleViewer.name],
		null);

	AppBuilderAclInsertOrUpdate(
		grApp,
		'record',
		'write',
		strTableName,
		'allow',
		'Allows users with process manager role write access to the table',
		[roleManager.name],
		null);		

	AppBuilderAclInsertOrUpdate(
		grApp,
		'record',
		'delete',
		strTableName,
		'allow',
		'Allows users with process admin role delete access to the table',
		[roleAdmin.name],
		null);

	// STATES
	var aStates = GetValue(business_process,'_states');

	// Creating the Choice Set
	var strChoiceSetSysId = RecordInsertOrUpdate(
		'sys_choice_set',
		{
			sys_scope: strScopeSysId,
			name: strTableName,
			element: 'state'
		},
		{
		},
		{
		});
	if (IsValidSysId(strChoiceSetSysId) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Could not create/update Choice Set for: ' + strTableName + '.state');
		return false;
	}

	for (var nState = 0; nState < aStates.length; nState++)
	{
		var state = aStates[nState];
		var strStateName = GetStringValue(GetValue(state,'name'));
		var strStateDescription = GetStringValue(GetValue(state,'description'));
		var nStateValue = GetIntegerValue(GetValue(state,'value'));
		var strChoiceSysId = RecordInsertOrUpdate(
			'sys_choice',
			{
				name: strTableName,
				element: 'state',
				value: GetStringValue(nStateValue), // without GetStringValue it results in "1.0"
				language: 'en'
			},
			{
			},
			{
				hint: strStateDescription,
				label: strStateName,
				sequence: nState + 1
			});
		if (IsValidSysId(strChoiceSysId) == false)
		{
			LogError('AppBuilderImplementBusinessProcess: Could not create/update choice: ' + strStateName);
			return false;
		}
	}

	// FIELDS

	var strDictOverrideSysId = RecordInsertOrUpdate(
		'sys_dictionary_override',
		{
			sys_scope: strScopeSysId,
			base_table: 'task',
			name: strTableName,
			element: 'state'
		},
		{
		},
		{
			read_only_override: true,
			read_only: true
		});

	if (IsValidSysId(strDictOverrideSysId) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Could not create/update dictionary override for: ' + strTableName + '.state!');
		return false;
	}

	var strDictOverrideSysId = RecordInsertOrUpdate(
		'sys_dictionary_override',
		{
			sys_scope: strScopeSysId,
			base_table: 'task',
			name: strTableName,
			element: 'number'
		},
		{
		},
		{
			read_only_override: true,
			read_only: true
		});

	if (IsValidSysId(strDictOverrideSysId) == false)
	{
		LogError('AppBuilderImplementBusinessProcess: Could not create/update dictionary override for: ' + strTableName + '.number!');
		return false;
	}

	// BUSINESS RULE (before insert or update)

	var strScript = '';
	strScript += "(function executeRule(current, previous /*null when async*/)\n";
	strScript += "{\n";
	strScript += "\tvar process = new "+strProcessClassName+"();\n";
	strScript += "\tprocess._BusinessRuleBeforeInsertOrUpdate(current, previous);\n";
	strScript += "\t\n";
	strScript += "})(current, previous);";

	var strBusinessRuleSysId = RecordInsertOrUpdate(
		'sys_script',
		{
			sys_scope: strScopeSysId,
			name: strProcessId + ' - before insert or update',
			collection: strTableName,
		},
		{
		},
		{
			active: 'true',
			advanced: 'true',
			order: -99999,
			description: 'Supports the "'+strProcessName+'" process.',
			script: strScript,
			when: 'before',
			action_insert: 'true',
			action_update: 'true',
		});


	// UI ACTIONS

	var aTransitions = GetValue(business_process,'_transitions');

	for (var nTransition = 0; nTransition < aTransitions.length; nTransition++)
	{
		var transition = aTransitions[nTransition];
		var strTransitionLabel = GetStringValue(GetValue(transition,'label'));
		var strTransitionId = GetStringValue(GetValue(transition,'id'));
		var strTargetState = GetStringValue(GetValue(transition,'target_state'));
		var strActionName = business_process.id + '_' + strTransitionId;
		var strComments = 'TODO';
		var nOrder = 500 + nTransition;
		var strUiActionSysId = RecordInsertOrUpdate(
			'sys_ui_action',
			{
				sys_scope: strScopeSysId,
				table: strTableName,
				action_name: strActionName,
			},
			{
			},
			{
				name: strTransitionLabel,
				order: nOrder,
				active: 'true',
				show_update: 'true',
				form_button: 'true',
				form_context_menu: 'true',
				form_style: 'primary',
				comments: strComments,
				condition:
					'new ' + strProcessClassName + "()._IsUiActionVisible(current,'"+strTransitionId+"')",
				script:
					'new ' + strProcessClassName + "()._UiActionTransition(current,'"+strTransitionId+"');"
			});

		if (IsValidSysId(strUiActionSysId) == false)
		{
			LogError('AppBuilderImplementBusinessProcess: Could not create/update UI Action: ' + strActionName);
			return false;
		}

		// add roles
		// sys_ui_action_role
	}


	// LIST VIEW

	var aFields = [
		'number',
		'state',
		'short_description'
		];

	var grUiView = GetViewRecord('Default view');
	if (IsValidRecord(grUiView) == true)
	{
		var grUiList = new GlideRecord('sys_ui_list');
		grUiList.addQuery('name','=',strTableName);
		grUiList.addQuery('view','=',grUiView.sys_id);
		grUiList.addNullQuery('sys_user');
		grUiList.addNullQuery('relationship');
		grUiList.addNullQuery('parent');
		grUiList.query();
		if (grUiList.getRowCount() == 0)
		{
			var strUiListSysId = RecordInsert(
				'sys_ui_list',
				{
					sys_scope: strScopeSysId,
					name: strTableName,
					view: grUiView.sys_id,
				});
			if (IsValidSysId(strUiListSysId) == true)
			{
				for (var nField = 0; nField < aFields.length; nField++)
				{
					var vField = aFields[nField];

					var strElement = '';
					if (IsObject(vField) == false)
					{
						strElement = GetStringValue(vField);
					}
					else
					{
						strElement = GetStringValue(GetValue(vField,'element'));
					}

					var grUiListElement = new GlideRecord('sys_ui_list_element');
					grUiListElement.initialize();
					grUiListElement.list_id = strUiListSysId;
					grUiListElement.position = nField;
					grUiListElement.element = strElement;
					grUiListElement.average_value = GetValue(vField,'average_value');
					grUiListElement.max_value = GetValue(vField,'max_value');
					grUiListElement.min_value = GetValue(vField,'min_value');
					grUiListElement.sum = GetValue(vField,'sum');

					var strUiListElementSysId = GlideRecordInsert(grUiListElement);

				}
			}

		}


		// Set the new fields
		for (var nField = 0; nField < aFields.length; nField++)
		{
			var vField = aFields[nField];

			var strElement = '';
			if (IsObject(vField) == false)
			{
				strElement = GetStringValue(vField);
			}
			else
			{
				strElement = GetStringValue(GetValue(vField,'element'));
			}

			var grUiListElement = new GlideRecord('sys_ui_list_element');
			grUiListElement.initialize();
			grUiListElement.list_id = grUiList.sys_id;
			grUiListElement.position = nField;
			grUiListElement.element = strElement;
			grUiListElement.average_value = GetValue(vField,'average_value');
			grUiListElement.max_value = GetValue(vField,'max_value');
			grUiListElement.min_value = GetValue(vField,'min_value');
			grUiListElement.sum = GetValue(vField,'sum');

			var strUiListElementSysId = GlideRecordInsert(grUiListElement);
			if (IsValidSysId(strUiListElementSysId) == false)
			{
				this.Error(
					StringFormat('Failed to re-define List (UI) for table "{0}" in view "{1}".',
						grUiList.name,
						grUiList.view.title));
				return false;
			}

		}
	}


	// APP SANITY

	AppSanity(grApp);

	return true;
}
